head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/**
 * @method
 * @name writeXFORMEditor
 * @description desc
 * @param {string} id desc
 * @param {string} webURL desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.writeXFORMEditor = function(id, webURL) {
    try {
        document.write('<OBJECT ID="' + id + '" style="WIDTH: 100%; HEIGHT: 100%" CODEBASE="/common/down/KINDEditor.cab#version=4,1,1,0"  CLASSID="clsid:D2240DE1-72A8-495a-B957-6DED60BE6D4B" >');
        document.write('<param name="WebServerURL" value="' + webURL + '">');
        document.write('<PARAM NAME="BaseURL" VALUE="/submission/">');
        document.write('<PARAM NAME="LayoutURL" VALUE="editor.do">');
        document.write('<PARAM NAME="DataURL" VALUE="editor.do">');
        document.write('<PARAM NAME="CmtURL" VALUE="editor.do">');
        document.write('<PARAM NAME="TimeConnect" VALUE="20">');
        document.write('<PARAM NAME="TimeReceive" VALUE="20">');
        document.write('<PARAM NAME="TimeDataReceive" VALUE="20">');
        document.write('<PARAM NAME="NATION" VALUE="ko">');
        document.write('<PARAM NAME="KINDFMVer" VALUE="7.5.0.2">');
        document.write('<PARAM NAME="AttachSize" VALUE="100">');
        document.write('</OBJECT>');
    } catch (E) {
        alert(E);
    }
};
