/**
 * @method
 * @name installXFORMEditor
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.installXFORMEditor = function() {
    try {
        document.write('<OBJECT ID="XForm" CODEBASE="/common/down/KINDEditor.cab#version=4,1,1,0"  CLASSID="clsid:D2240DE1-72A8-495a-B957-6DED60BE6D4B" STYLE="DISPLAY: NONE" >');
        document.write('</OBJECT>');
    } catch (E) {
        alert(E);
    }
};
